using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class StrategyDraftReviewTests{[Fact]public void Mismatched_admission_is_not_ready(){var draft=StrategyDraftRules.Create("s","ABC",Array.Empty<StrategyDraftParameter>());var manifest=new StrategyCapabilityManifest("other","DEF",false,false,false,false,false,false,false);var env=new StrategyAdmissionEnvelope(StrategyAdmissionState.Admitted,manifest,new StrategyFeatureSelection(Array.Empty<StrategyFeature>()),"Q","DEF");var artifact=StrategyAdmissionArtifactRules.Create(env);var review=StrategyDraftReviewRules.Create(draft,artifact);Assert.False(review.ReadyForResearch);Assert.False(review.CanSubmitOrders);Assert.NotEmpty(review.Diagnostics);}}
